    assert.equal(page.total, 1);
    assert.equal(page.items[0]?.id, comment.id);
  }
  assert.equal((await query(enterprise, "flaky", { kinds: ["comment"] })).total, 1);
  assert.equal((await query(enterprise, "kind:issue in:comments flaky", { kinds: ["project"] })).total, 2);
  assert.equal((await query(enterprise, "status:open kind: kind:comment flaky")).total, 1);
  assert.equal((await query(enterprise, `project:${enterprise.project.id} flaky`, {
    projectId: growth.project.id,
