  assert.equal((await query(enterprise, "flaky", { projectId: enterprise.project.id })).total, 2);
  assert.deepEqual(parseSearchQuery("flaky", true, ["comment"]).kinds, ["comment"]);
  assert.equal(parseSearchQuery("A  B", true).text, "A  B");

