  const growthComment = await comments.createComment(growth.actors.member, {
    orgId: growth.org.id, issueId: growthIssue.id, body: "kind:comment growth marker",
    parentId: null, mentionedUserIds: [],
  });
  for (const kinds of [[...ALL_SEARCH_KINDS], ["comment"] as const, []]) {
    const page = await query(growth, "kind:comment growth marker", { kinds: [...kinds] });
